    .sort((a, b) => b.updated.localeCompare(a.updated))
    .slice(0, 3);

  const summary = [
    {
      title: "Open issues",
      value: openIssues,
      hint: `Across ${projects.length} projects`,
      icon: AlertCircle,
    },
    {
      title: "Active projects",
      value: active.length,
      hint: `${paused.length} paused, 1 archived`,
      icon: FolderKanban,
    },
    {
      title: "Busiest project",
      value: busiest.key,
      hint: `${busiest.name}, ${busiest.issues} open issues`,
      icon: Pause,
    },
    {
      title: "Team members",
      value: 8,
      hint: `${user.name} is the ${user.role.toLowerCase()}`,
